#!/usr/bin/env python3
import sys, os, json, argparse, re, configparser, urllib.parse, html
from valuefmt import display, json_output
try:
 import tomllib
except ImportError:
 tomllib=None

def parse_data(raw, fmt, name=''):
    if fmt=='auto':
        ext=os.path.splitext(name)[1].lower()
        fmt={'.json':'json','.json5':'json','.toml':'toml','.ini':'ini','.conf':'ini','.config':'ini','.properties':'ini','.qs':'querystring','.yaml':'yaml','.yml':'yaml'}.get(ext,'')
        if not fmt: raise ValueError('unable to auto detect format')
    if fmt=='json': return json.loads(raw)
    if fmt=='toml':
        if tomllib: return tomllib.loads(raw)
        out={}; cur=out
        for line in raw.splitlines():
            line=line.split('#',1)[0].strip()
            if not line: continue
            if line.startswith('[') and line.endswith(']'):
                cur=out
                for bit in line[1:-1].split('.'): cur=cur.setdefault(bit,{})
            elif '=' in line:
                k,v=line.split('=',1); v=v.strip()
                try: cur[k.strip()]=json.loads(v)
                except: cur[k.strip()]=v.strip('\"\'')
        return out
    if fmt=='querystring':
        d={}
        for k,v in urllib.parse.parse_qsl(raw,keep_blank_values=True): d[k]=v
        return d
    if fmt=='ini':
        p=configparser.ConfigParser(); p.read_string(raw)
        out={'default':dict(p.defaults())}
        out.update({s:dict(p.items(s)) for s in p.sections()})
        return out
    if fmt in ('yaml','cbor'): return json.loads(raw)
    raise ValueError('unsupported format')

def truth(v): return bool(v)
def stringify(v):
    if v is None: return ''
    if v is True:return 'true'
    if v is False:return 'false'
    if isinstance(v,(dict,list)): return json.dumps(v,ensure_ascii=False,separators=(', ', ': '))
    return str(v)
def expression(s,ctx):
    s=s.strip()
    # Jinja literals/operators
    s=re.sub(r'\btrue\b','True',s); s=re.sub(r'\bfalse\b','False',s); s=re.sub(r'\bnone\b|\bnull\b','None',s)
    s=re.sub(r'\bnot\b','not',s)
    try:return eval(s,{'__builtins__':{},'range':range,'len':len,'str':str,'int':int,'float':float,'min':min,'max':max,'dict':dict,'list':list},ctx)
    except Exception:
        m=re.fullmatch(r'([\w.]+)',s)
        if m:
            x=ctx
            for part in s.split('.'): x=x.get(part) if isinstance(x,dict) else None
            return x
        return ''
def esc(v,opts):
    mode=opts.get('autoescape','none')
    x=stringify(v)
    if mode=='html': return html.escape(x,quote=True).replace('&#x27;','&#x27;')
    if mode=='json': return json.dumps(x,ensure_ascii=False)[1:-1]
    return x
def render(t,ctx,opts):
    vs,ve=opts.get('variable-start','{{'),opts.get('variable-end','}}')
    cs,ce=opts.get('comment-start','{#'),opts.get('comment-end','#}')
    t=re.sub(re.escape(cs)+'.*?'+re.escape(ce),'',t,flags=re.S)
    t=re.sub(re.escape(vs)+r'([\s\S]*?)'+re.escape(ve),lambda m: esc(expression(m.group(1).split('|')[0],ctx),opts),t)
    return t

def main():
    ap=argparse.ArgumentParser(add_help=False)
