    def visit_Attribute(self, node):
        self.generic_visit(node)
        return ast.copy_location(ast.Call(
            func=ast.Name(id="_attr", ctx=ast.Load()),
            args=[node.value, ast.Constant(node.attr)], keywords=[]), node)

    def visit_BinOp(self, node):
        self.generic_visit(node)
        if isinstance(node.op, ast.Add):
            return ast.copy_location(ast.Call(
                func=ast.Name(id="_add", ctx=ast.Load()),
                args=[node.left, node.right], keywords=[]), node)
        return node


def _prepare(source):
    s = source.strip()
    # Rewrite literals and concatenation only outside quoted strings.
    out=[]; quote=None; escaped=False; i=0
    while i < len(s):
        ch=s[i]
        if quote:
            out.append(ch)
            if escaped: escaped=False
            elif ch=='\\': escaped=True
            elif ch==quote: quote=None
            i+=1; continue
        if ch in ('"', "'"):
            quote=ch; out.append(ch); i+=1; continue
        if ch=='~':
            out.append(' + '); i+=1; continue
        word=re.match(r"[A-Za-z_]\w*",s[i:])
        if word:
            token=word.group(0)
            out.append({'true':'True','false':'False','none':'None','null':'None'}.get(token.lower(),token))
            i+=len(token); continue
        out.append(ch); i+=1
    s=''.join(out)
    s = re.sub(r"\bnot\s+in\b", "not in", s)
    # Jinja's `is none` is Python's `is None` after literal conversion.
    s = re.sub(r"\bis\s+none\b", "is None", s, flags=re.I)
    s = re.sub(r"\bis\s+not\s+none\b", "is not None", s, flags=re.I)
    tests = r"iterable|sequence|mapping|map|number|integer|string|boolean|bool|odd|even"
    s = re.sub(r"(.+?)\s+is\s+(not\s+)?(" + tests + r")\b",
               lambda m: ("(not " if m.group(2) else "(") + "_test(" + m.group(1).strip() + ", '" + m.group(3) + "'))",
               s, flags=re.I)
    s = re.sub(r"\b([A-Za-z_]\w*)\s+is\s+defined\b", r"_defined(\1)", s)
    s = re.sub(r"\b([A-Za-z_]\w*)\s+is\s+undefined\b", r"(not _defined(\1))", s)
