def _lookup(context, name):
    if isinstance(context, dict):
        return context.get(name, Undefined(name))
    return getattr(context, name, Undefined(name))


def _attr(value, name):
    if isinstance(value, dict):
        return value.get(name, Undefined(name))
    if isinstance(value, (list, tuple, str)) and name == "length":
        return len(value)
    try:
        return getattr(value, name)
    except (AttributeError, TypeError):
        return Undefined(name)


def _add(left, right):
    if isinstance(left, str) or isinstance(right, str):
        def text(v):
            if v is None:
                return "none"
            if v is True:
                return "true"
            if v is False:
                return "false"
            return str(v)
        return text(left) + text(right)
    return left + right

def _div(left, right):
    if right == 0:
        if left == 0: return math.nan
        negative = (float(left) < 0) ^ (math.copysign(1.0, float(right)) < 0)
        return -math.inf if negative else math.inf
    return left / right

