"""Common MiniJinja filters used by the CLI renderer and expression evaluator."""
import json
import math


def apply_filter(value, name, *args):
    """Apply one common MiniJinja filter; unknown filters return value unchanged."""
    if name == "upper": return str(value).upper()
    if name == "lower": return str(value).lower()
    if name == "capitalize": return str(value).capitalize()
    if name == "title": return str(value).title()
    if name == "trim": return str(value).strip()
    if name == "length": return len(value) if value is not None else 0
    if name == "default":
        fallback = args[0] if args else ""
        boolean = len(args) > 1 and bool(args[1])
        undefined = value.__class__.__name__ == "Undefined"
        return fallback if undefined or (boolean and not value) else value
    if name == "first":
        try: return next(iter(value))
        except (TypeError, StopIteration): return None
    if name == "last":
        try: return value[-1] if not isinstance(value, dict) else next(reversed(value))
        except (TypeError, IndexError, KeyError): return None
    if name == "join":
        sep = str(args[0]) if args else ""
        return sep.join(str(x) for x in value)
    if name == "sort":
        reverse = bool(args[0]) if args else False
        return sorted(value, reverse=reverse)
    if name == "reverse":
        return list(reversed(value))
    if name == "sum":
        return sum(value)
    if name == "min": return min(value) if value else None
    if name == "max": return max(value) if value else None
    if name == "abs": return abs(value)
    if name == "round": return round(value, int(args[0]) if args else 0)
    if name == "replace":
        old = str(args[0]) if args else ""
        new = str(args[1]) if len(args) > 1 else ""
        return str(value).replace(old, new)
    if name == "tojson":
        indent = args[0] if args else None
        if isinstance(indent, dict): indent = indent.get("indent")
        if indent is True: indent = 2
        if indent is False: indent = None
        return json.dumps(value, ensure_ascii=False, indent=indent, separators=None if indent else (",", ":"))
    if name == "dictsort":
        if not isinstance(value, dict): return value
        case_sensitive = bool(args[0]) if args else False
        by = str(args[1]) if len(args) > 1 else "key"
        reverse = bool(args[2]) if len(args) > 2 else False
        pairs = list(value.items())
        if not case_sensitive and by == "key": pairs.sort(key=lambda kv: str(kv[0]).lower(), reverse=reverse)
        else: pairs.sort(key=lambda kv: kv[0 if by == "key" else 1], reverse=reverse)
        return [list(x) for x in pairs]
    if name == "selectattr":
        attr = args[0] if args else ""
        test = str(args[1]) if len(args) > 1 else "truthy"
        target = args[2] if len(args) > 2 else None
        def get(item):
            if isinstance(item, dict): return item.get(attr)
            return getattr(item, str(attr), None)
        def ok(item):
            v = get(item)
            if test in ("equalto", "eq", "=="): return v == target
            if test in ("ne", "!="): return v != target
            if test == "in": return v in target if target is not None else False
            if test in ("gt", ">"): return v is not None and v > target
            if test in ("ge", ">="): return v is not None and v >= target
            if test in ("lt", "<"): return v is not None and v < target
            if test in ("le", "<="): return v is not None and v <= target
            if test == "defined": return v is not None
            if test == "undefined": return v is None
            if test == "none": return v is None
            return bool(v)
        return [item for item in value if ok(item)]
    if name == "map":
        attr = None
        if args and isinstance(args[0], dict): attr = args[0].get("attribute")
        if attr is not None:
            return [item.get(attr) if isinstance(item, dict) else getattr(item, str(attr), None) for item in value]
        return list(value)
    if name == "list": return list(value)
    return value

